// Argus /api/news listing items carry { id, headline, datePublished, ... }.
// Construct the canonical public article URL by slugifying the headline:
//   https://www.argusmedia.com/en/news-and-insights/latest-market-news/<id>-<slug>
// Slug rule: lowercase, replace every run of non-alphanumerics with a single
// hyphen, strip leading/trailing hyphens. Apostrophes, commas, colons all
// collapse to '-' the same way (verified against Argus's own canonical URLs).
const items = $input.all();
const HOST_ALLOWLIST = /^https:\/\/www\.argusmedia\.com\//;
function slugify(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}
const out = [];
const seen = new Set();
let droppedNoId = 0, droppedNoHeadline = 0, droppedNoDate = 0, droppedBadHost = 0, droppedDup = 0;
for (const wrap of items) {
  const news = wrap.json || {};
  const list = Array.isArray(news.items) ? news.items : [];
  for (const it of list) {
    const id = it.id;
    if (id === undefined || id === null || id === '') { droppedNoId++; continue; }
    const slug = slugify(it.headline);
    if (!slug) { droppedNoHeadline++; continue; }
    const url = `https://www.argusmedia.com/en/news-and-insights/latest-market-news/${id}-${slug}`;
    if (!HOST_ALLOWLIST.test(url)) { droppedBadHost++; continue; }
    if (!it.datePublished) { droppedNoDate++; continue; }
    if (seen.has(url)) { droppedDup++; continue; }
    seen.add(url);
    out.push({ url, source_date: String(it.datePublished) });
  }
}
return [{ json: { urls: out, urlsEmitted: out.length, droppedNoId, droppedNoHeadline, droppedNoDate, droppedBadHost, droppedDup } }];

// Shape into the /research-ingest contract. urls already carries
// {url, source_date} from the extractor.
const urls = $input.first().json.urls || [];
if (!urls.length) {
  throw new Error('no_urls_extracted — upstream Argus call returned 0 publishable items');
}
if (urls.length > 100) urls.length = 100; // cap to /research-ingest max_length
return [{
  json: {
    source_type: 'Website',
    source_name: 'Argus Media',
    source_category: 'News',
    urls,
  },
}];

// Pull together the run summary for the success Slack message.
//   - upstream:  /research-ingest response  (queued, skipped_dedup, status)
//   - extract:   Code: Extract URLs output  (urlsEmitted, drop counters)
const upstream = $input.first().json || {};
const extract = $('Code: Extract URLs').first().json || {};
return [{ json: {
  status: upstream.status || 'queued',
  urlsEmitted: extract.urlsEmitted ?? 0,
  queued: upstream.queued ?? 0,
  skipped_dedup: upstream.skipped_dedup ?? 0,
  droppedNoId: extract.droppedNoId ?? 0,
  droppedNoHeadline: extract.droppedNoHeadline ?? 0,
  droppedNoDate: extract.droppedNoDate ?? 0,
  droppedBadHost: extract.droppedBadHost ?? 0,
  droppedDup: extract.droppedDup ?? 0,
  source_name: 'Argus Media',
}}];

// Pull together the error context for the error Slack message.
// Fires once per failed POST /research-ingest (after retries exhausted).
const raw = $input.first().json || {};
const extract = $('Code: Extract URLs').first().json || {};
const status = raw.statusCode || raw.status || 502;
const errMsg = typeof raw.error === 'string' ? raw.error
  : (raw.message || raw.body || JSON.stringify(raw).slice(0, 500));
return [{ json: {
  status: 'error',
  upstream_status: status,
  error: String(errMsg).slice(0, 500),
  urlsEmitted: extract.urlsEmitted ?? 0,
  source_name: 'Argus Media',
}}];

