// Zyte returns { httpResponseBody: <base64>, statusCode, ... }.
// Decode to UTF-8, parse the JSON, surface in the same shape Argus's
// direct response uses ({ totalHitCount, hitCount, items, itemsCursor })
// so the downstream Code: Extract URLs node treats both branches the same.
const r = $input.first().json;
const b64 = r.httpResponseBody;
if (!b64) {
  throw new Error('zyte_empty_response — no httpResponseBody field returned');
}
let parsed;
try {
  parsed = JSON.parse(Buffer.from(b64, 'base64').toString('utf8'));
} catch (e) {
  throw new Error('zyte_decode_failed: ' + e.message);
}
return [{ json: parsed }];
